import streamlit as stimport pandas as pdimport numpy as npimport yfinance as yfimport plotly.graph_objects as go# ============================================================# 1. DASHBOARD SETTINGS# ============================================================st.set_page_config(    page_title="Portfolio Risk Dashboard",    page_icon="📊",    layout="wide")st.title("Portfolio Risk & Performance Dashboard")st.caption(    "Analysis of portfolio performance, market risk, stress testing "    "and benchmark performance.")# ============================================================# 2. LOAD PORTFOLIO DATA# ============================================================prices = pd.read_csv(    "../data/adj_close.csv",    index_col=0,    parse_dates=True)# Make sure data is sorted chronologicallyprices = prices.sort_index()# Remove rows where all assets are missingprices = prices.dropna(how="all")# Daily returnsreturns = prices.pct_change().dropna()# Equal weightsn_assets = len(returns.columns)weights = np.repeat(    1 / n_assets,    n_assets)# Portfolio daily returnsportfolio_returns = pd.Series(    np.dot(returns, weights),    index=returns.index,    name="Portfolio")# ============================================================# 3. PORTFOLIO PERFORMANCE CALCULATIONS# ============================================================# Annualized mean returnannual_return = portfolio_returns.mean() * 252# Annualized volatilityannual_volatility = (    portfolio_returns.std() * np.sqrt(252))# Risk-free raterisk_free_rate = 0.0225# Sharpe ratiosharpe_ratio = (    (annual_return - risk_free_rate)    / annual_volatility)# Portfolio cumulative growthportfolio_growth = (    1 + portfolio_returns).cumprod()# Running peakrunning_peak = portfolio_growth.cummax()# Drawdowndrawdown = (    portfolio_growth - running_peak) / running_peak# Maximum drawdownmax_drawdown = drawdown.min()# ============================================================# 4. VALUE AT RISK# ============================================================# Historical 95% VaRvar_95 = portfolio_returns.quantile(0.05)# Conditional VaR / Expected Shortfallcvar_95 = portfolio_returns[    portfolio_returns <= var_95].mean()# Convert negative return thresholds into positive loss magnitudesvar_loss = -var_95cvar_loss = -cvar_95# ============================================================# 5. 30-DAY ROLLING ANNUALIZED VOLATILITY# ============================================================rolling_volatility = (    portfolio_returns    .rolling(window=30)    .std()    * np.sqrt(252))# ============================================================# 6. 95% HISTORICAL VaR BACKTEST# ============================================================# Exception occurs when actual return is worse than VaRvar_exceptions = portfolio_returns < var_95exception_count = int(var_exceptions.sum())exception_rate = (    var_exceptions.mean())expected_exception_rate = 0.05exception_difference = (    exception_rate - expected_exception_rate)# ============================================================# 7. RISK CONTRIBUTION# ============================================================# Daily covariance matrixcov_matrix = returns.cov()# Daily portfolio volatility from covariance matrixportfolio_volatility_daily = np.sqrt(    np.dot(        weights,        np.dot(cov_matrix, weights)    ))# Marginal contribution to riskmarginal_contribution = np.dot(    cov_matrix,    weights)# Component contribution to riskrisk_contribution = (    weights * marginal_contribution) / portfolio_volatility_daily# Percentage contributionrisk_contribution_pct = (    risk_contribution    / portfolio_volatility_daily) * 100risk_contribution_series = pd.Series(    risk_contribution_pct,    index=returns.columns,    name="Risk Contribution (%)").sort_values(ascending=False)# ============================================================# 8. COVID-19 STRESS TEST# ============================================================covid_returns = returns.loc[    "2020-02-01":"2020-04-30"].dropna()covid_portfolio_returns = pd.Series(    np.dot(covid_returns, weights),    index=covid_returns.index,    name="COVID Portfolio Returns")# COVID cumulative growthcovid_growth = (    1 + covid_portfolio_returns).cumprod()# COVID running peakcovid_peak = covid_growth.cummax()# COVID drawdowncovid_drawdown = (    covid_growth - covid_peak) / covid_peak# Maximum COVID drawdowncovid_max_drawdown = covid_drawdown.min()# COVID annualized volatilitycovid_volatility = (    covid_portfolio_returns.std()    * np.sqrt(252))# Pre-COVID "normal" volatilitypre_covid_returns = returns.loc[    "2019-01-01":"2020-01-31"].dropna()pre_covid_portfolio_returns = pd.Series(    np.dot(pre_covid_returns, weights),    index=pre_covid_returns.index)pre_covid_volatility = (    pre_covid_portfolio_returns.std()    * np.sqrt(252))# ============================================================# 9. S&P 500 BENCHMARK# ============================================================benchmark_data = yf.download(    "^GSPC",    start="2019-01-01",    end="2026-01-01",    auto_adjust=False,    progress=False)# Handle yfinance MultiIndex / normal columnsif isinstance(benchmark_data.columns, pd.MultiIndex):    if ("Close", "^GSPC") in benchmark_data.columns:        benchmark_prices = benchmark_data[            ("Close", "^GSPC")        ]    else:        benchmark_prices = benchmark_data["Close"].iloc[:, 0]else:    benchmark_prices = benchmark_data["Close"]benchmark_prices = benchmark_prices.dropna()benchmark_returns = (    benchmark_prices    .pct_change()    .dropna())benchmark_returns.name = "S&P 500"# ============================================================# 10. ALIGN PORTFOLIO + BENCHMARK# ============================================================comparison = pd.concat(    [        portfolio_returns,        benchmark_returns    ],    axis=1,    join="inner").dropna()comparison.columns = [    "Portfolio",    "S&P 500"]# ============================================================# 11. PORTFOLIO BETA# ============================================================beta = (    comparison["Portfolio"].cov(comparison["S&P 500"])    / comparison["S&P 500"].var())# ============================================================# 12. NORMALIZED PORTFOLIO VS S&P 500 GROWTH# ============================================================growth = (    1 + comparison).cumprod()# ============================================================# 13. VALIDATION CHECKS# ============================================================weights_sum = weights.sum()risk_contribution_sum = (    risk_contribution_pct.sum())# Check whether calculations are internally consistentweights_check = np.isclose(    weights_sum,    1.0)risk_contribution_check = np.isclose(    risk_contribution_sum,    100.0)# ============================================================# 14. PORTFOLIO OVERVIEW# ============================================================st.header("Portfolio Overview")col1, col2, col3, col4 = st.columns(4)col1.metric(    "Annualized Mean Return",    f"{annual_return:.2%}")col2.metric(    "Annualized Volatility",    f"{annual_volatility:.2%}")col3.metric(    "Sharpe Ratio",    f"{sharpe_ratio:.2f}")col4.metric(    "Maximum Drawdown",    f"{max_drawdown:.2%}")# ============================================================# 15. MARKET RISK# ============================================================st.header("Market Risk")col1, col2 = st.columns(2)col1.metric(    "95% Historical VaR (1-Day)",    f"{var_loss:.2%}")col2.metric(    "95% CVaR / Expected Shortfall",    f"{cvar_loss:.2%}")st.caption(    "VaR represents the estimated 1-day loss threshold at the 95% confidence level. "    "CVaR represents the average loss on observations beyond that threshold.")# ============================================================# 16. PORTFOLIO PERFORMANCE# ============================================================st.header("Portfolio Performance")fig_performance = go.Figure()fig_performance.add_trace(    go.Scatter(        x=portfolio_growth.index,        y=portfolio_growth,        mode="lines",        name="Portfolio"    ))fig_performance.update_layout(    height=420,    xaxis_title="Date",    yaxis_title="Growth of €1",    hovermode="x unified",    margin=dict(l=20, r=20, t=30, b=20))st.plotly_chart(    fig_performance,    use_container_width=True)# ============================================================# 17. ROLLING VOLATILITY# ============================================================st.header("30-Day Rolling Annualized Volatility")fig_volatility = go.Figure()fig_volatility.add_trace(    go.Scatter(        x=rolling_volatility.index,        y=rolling_volatility,        mode="lines",        name="30-Day Rolling Volatility"    ))fig_volatility.update_layout(    height=400,    xaxis_title="Date",    yaxis_title="Annualized Volatility",    yaxis_tickformat=".0%",    hovermode="x unified",    margin=dict(l=20, r=20, t=30, b=20))st.plotly_chart(    fig_volatility,    use_container_width=True)# ============================================================# 18. VaR BACKTEST# ============================================================st.header("95% Historical VaR Backtest")col1, col2, col3 = st.columns(3)col1.metric(    "VaR Exceptions",    f"{exception_count}")col2.metric(    "Actual Exception Rate",    f"{exception_rate:.2%}")col3.metric(    "Expected Exception Rate",    f"{expected_exception_rate:.2%}")if abs(exception_difference) < 0.01:    st.success(        f"The actual exception rate of {exception_rate:.2%} "        f"is very close to the expected 5.00% rate. "        "This indicates reasonable exception-frequency calibration "        "for the historical VaR estimate over the sample period."    )else:    st.warning(        f"The actual exception rate of {exception_rate:.2%} "        f"differs from the expected 5.00% rate. "        "This may indicate that the historical VaR model is not "        "fully capturing the portfolio's observed tail risk."    )st.caption(    "Note: this is an in-sample historical VaR backtest. "    "A formal out-of-sample backtest would use VaR estimates "    "generated using only information available before each observation.")# ============================================================# 19. RISK CONTRIBUTION# ============================================================st.header("Risk Contribution by Holding")fig_risk = go.Figure()fig_risk.add_trace(    go.Bar(        x=risk_contribution_series.values,        y=risk_contribution_series.index,        orientation="h",        name="Risk Contribution"    ))fig_risk.update_layout(    height=450,    xaxis_title="Contribution to Portfolio Risk (%)",    yaxis_title="Holding",    xaxis_ticksuffix="%",    margin=dict(l=20, r=20, t=30, b=20))st.plotly_chart(    fig_risk,    use_container_width=True)st.caption(    "Risk contribution measures each holding's contribution to total "    "portfolio volatility, accounting for both its weight and covariance "    "with the other holdings.")# ============================================================# 20. COVID-19 STRESS TEST# ============================================================st.header("COVID-19 Stress Test")col1, col2 = st.columns(2)col1.metric(    "COVID-19 Maximum Drawdown",    f"{covid_max_drawdown:.2%}")col2.metric(    "COVID-19 Annualized Volatility",    f"{covid_volatility:.2%}")fig_covid = go.Figure()fig_covid.add_trace(    go.Scatter(        x=covid_drawdown.index,        y=covid_drawdown,        mode="lines",        name="COVID-19 Drawdown"    ))fig_covid.update_layout(    height=400,    xaxis_title="Date",    yaxis_title="Drawdown",    yaxis_tickformat=".0%",    hovermode="x unified",    margin=dict(l=20, r=20, t=30, b=20))st.plotly_chart(    fig_covid,    use_container_width=True)st.caption(    "Stress period: February 1, 2020 to April 30, 2020.")# ============================================================# 21. COVID VS PRE-COVID VOLATILITY# ============================================================st.subheader("Volatility: Pre-COVID vs COVID")col1, col2 = st.columns(2)col1.metric(    "Pre-COVID Volatility",    f"{pre_covid_volatility:.2%}")col2.metric(    "COVID Volatility",    f"{covid_volatility:.2%}")# ============================================================# 22. BENCHMARK ANALYSIS# ============================================================st.header("Benchmark Analysis")col1, col2 = st.columns(2)col1.metric(    "Portfolio Beta vs S&P 500",    f"{beta:.2f}")# ============================================================# 23. PORTFOLIO VS S&P 500# ============================================================st.subheader("Portfolio vs S&P 500 Price Index")fig_benchmark = go.Figure()fig_benchmark.add_trace(    go.Scatter(        x=growth.index,        y=growth["Portfolio"],        mode="lines",        name="Portfolio"    ))fig_benchmark.add_trace(    go.Scatter(        x=growth.index,        y=growth["S&P 500"],        mode="lines",        name="S&P 500"    ))fig_benchmark.update_layout(    height=420,    xaxis_title="Date",    yaxis_title="Growth of €1",    hovermode="x unified",    margin=dict(l=20, r=20, t=30, b=20))st.plotly_chart(    fig_benchmark,    use_container_width=True)# ============================================================# 24. MODEL VALIDATION# ============================================================with st.expander("Model & Calculation Checks"):    st.write(        f"**Number of holdings:** {n_assets}"    )    st.write(        f"**Portfolio weights sum:** {weights_sum:.4f}"    )    st.write(        f"**Risk contribution sum:** "        f"{risk_contribution_sum:.2f}%"    )    st.write(        f"**VaR exception count:** {exception_count}"    )    st.write(        f"**Actual exception rate:** "        f"{exception_rate:.2%}"    )    if weights_check:        st.success(            "Portfolio weights sum to 100%."        )    else:        st.error(            "Portfolio weights do not sum to 100%."        )    if risk_contribution_check:        st.success(            "Risk contributions sum to approximately 100%."        )    else:        st.error(            "Risk contributions do not sum to 100%."        )# ============================================================# 25. FOOTER# ============================================================st.divider()st.caption(    "Portfolio Risk & Performance Dashboard | "    "Historical market data | Equal-weight portfolio")